set stem = p.stem,
    options_json = p.options_json,
    correct_answer_json = p.correct_answer_json,
    markscheme_points_json = p.markscheme_points_json,
    explanation = p.explanation,
    content_blocks_json = p.content_blocks_json,
    response_schema_json = p.response_schema_json,
    autograde_rules_json = p.autograde_rules_json,
    teacher_notes = concat_ws(' | ', nullif(q.teacher_notes, ''), 'Content accuracy hotfix 2026-05-04: removed public Pairs helper text where present, widened fill-gap accepted answers, and corrected tested wording defects.')
from patch_rows p
where q.external_id = p.external_id;

do $$
declare
  remaining_pairs integer;
  vlookup_accepts_b12 boolean;
  chart_accepts_short_forms boolean;
  clock_wording_ok boolean;
begin
  select count(*) into remaining_pairs
  from public.questions
  where is_active = true
    and stem ilike '%Pairs:%';

  if remaining_pairs <> 0 then
    raise exception 'Content hotfix failed: % active questions still contain public Pairs helper text', remaining_pairs;
  end if;

  select public.answer_text_match_group(
    'b12',
    autograde_rules_json -> 'gaps' -> 0 -> 'accepted_groups',
    'phrase',
    'exact'
  ) is not null into vlookup_accepts_b12
  from public.questions
  where external_id = 'spreadsheet-applications.past_paper.topics_03_04.q034';

  if not coalesce(vlookup_accepts_b12, false) then
    raise exception 'Content hotfix failed: VLOOKUP answer b12 is not accepted';
  end if;

  select public.answer_text_match_group(
    'column',
    autograde_rules_json -> 'gaps' -> 0 -> 'accepted_groups',
    'phrase',
    'exact'
  ) is not null
  and public.answer_text_match_group(
    'bar',
    autograde_rules_json -> 'gaps' -> 0 -> 'accepted_groups',
    'phrase',
    'exact'
  ) is not null
  and public.answer_text_match_group(
    'pie',
    autograde_rules_json -> 'gaps' -> 0 -> 'accepted_groups',
    'phrase',
    'exact'
  ) is not null into chart_accepts_short_forms
  from public.questions
  where external_id = 'spreadsheet-applications.practice_bank.topic_04_spreadsheet.q040';

  if not coalesce(chart_accepts_short_forms, false) then
    raise exception 'Content hotfix failed: chart short-form answers are not accepted';
  end if;

  select stem ilike '%3 billion cycles per second%' into clock_wording_ok
  from public.questions
  where external_id = 'computer-hardware.practice_bank.topic_05_06_hardware_networks.q009';

  if not coalesce(clock_wording_ok, false) then
    raise exception 'Content hotfix failed: clock-speed wording was not corrected';
  end if;
end $$;

commit;
